// ---------------------------------------------------------------------------
// CRUD — Provider
// ---------------------------------------------------------------------------

/// Insert a provider. Violating the UNIQUE `key` constraint returns
/// [`sqlx::Error::Database`] (UNIQUE violation).
pub async fn insert_provider(pool: &SqlitePool, p: &Provider) -> Result<(), sqlx::Error> {
    // Bind Option conversions to locals so the temporaries live long enough
    // for the sqlx macro's borrow checker.
    let max_concurrency = p.max_concurrency.map(|v| v as i64);
    let max_queue_depth = p.max_queue_depth.map(|v| v as i64);
    let queue_wait_timeout_ms = p.queue_wait_timeout_ms.map(|v| v as i64);
    sqlx::query!(
        "INSERT INTO provider (id, key, name, endpoint, weight, created_at, updated_at, \
         max_concurrency, max_queue_depth, queue_wait_timeout_ms) \
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
        p.id,
        p.key,
        p.name,
        p.endpoint,
        p.weight,
        p.created_at,
        p.updated_at,
        max_concurrency,
        max_queue_depth,
        queue_wait_timeout_ms,
    )
    .execute(pool)
    .await?;
    Ok(())
}

/// Fetch a single provider by id; `Err(RowNotFound)` when absent.
pub async fn get_provider(pool: &SqlitePool, id: &str) -> Result<Provider, sqlx::Error> {
    let row = sqlx::query_as!(
        ProviderRow,
        r#"SELECT id as "id!", key, name, endpoint, weight, created_at, updated_at,
                  max_concurrency, max_queue_depth, queue_wait_timeout_ms
           FROM provider WHERE id = ?"#,
        id
    )
    .fetch_one(pool)
    .await?;
    Ok(row.into())
}

/// All providers, ordered by `created_at`.
pub async fn list_providers(pool: &SqlitePool) -> Result<Vec<Provider>, sqlx::Error> {
    let rows = sqlx::query_as!(
        ProviderRow,
        r#"SELECT id as "id!", key, name, endpoint, weight, created_at, updated_at,
                  max_concurrency, max_queue_depth, queue_wait_timeout_ms
           FROM provider ORDER BY created_at"#
    )
    .fetch_all(pool)
    .await?;
    Ok(rows.into_iter().map(Into::into).collect())
}

/// Update a provider's mutable fields.
pub async fn update_provider(pool: &SqlitePool, p: &Provider) -> Result<(), sqlx::Error> {
    let max_concurrency = p.max_concurrency.map(|v| v as i64);
    let max_queue_depth = p.max_queue_depth.map(|v| v as i64);
    let queue_wait_timeout_ms = p.queue_wait_timeout_ms.map(|v| v as i64);
    sqlx::query!(
        "UPDATE provider SET key = ?, name = ?, endpoint = ?, weight = ?, updated_at = ?, \
         max_concurrency = ?, max_queue_depth = ?, queue_wait_timeout_ms = ? \
         WHERE id = ?",
        p.key,
        p.name,
        p.endpoint,
        p.weight,
        p.updated_at,
        max_concurrency,
        max_queue_depth,
        queue_wait_timeout_ms,
        p.id,
    )
    .execute(pool)
    .await?;
    Ok(())
}

/// Delete a provider (CASCADE removes its models/keys and tenant_provider links).
pub async fn delete_provider(pool: &SqlitePool, id: &str) -> Result<(), sqlx::Error> {
    sqlx::query!("DELETE FROM provider WHERE id = ?", id)
        .execute(pool)
        .await?;
    Ok(())
}

